/// <summary>
/// Method to salve METScanSupplier field to Sales Order type in case the Transaction is created from Sales order.
/// </summary>
/// <param name="sender">Get Table buffer</param>
/// <param name="e"> Get table event args</param>
[DataEventHandler(tableStr(TAMRebateTrans), DataEventType::Inserting)]
public static void TAMRebateTrans_onInserting(Common sender, DataEventArgs e)
{
    TAMRebateTrans rebateTrans = sender as TAMRebateTrans;
    if(rebateTrans.RebateRefId)
    {
        rebateTrans.METScanSupplier = METScanSupplier::SalesOrder;
    }
}
